/* HEATING_COMPACT_20260918 */
.bubble-climate-container {
  height: 90px !important;
  min-height: 90px !important;
  border-radius: 16px !important;
  background: var(--ha-card-background, var(--card-background-color, #fff)) !important;
  border: 1px solid var(--divider-color, #e5e7eb) !important;
  box-shadow: 0 2px 6px rgba(15,23,42,.04) !important;
  opacity: 1 !important;
}
.bubble-climate-container .bubble-wrapper {
  display: grid !important;
  position: relative !important;
  grid-template-columns: minmax(0, 1fr) 152px !important;
  grid-template-rows: 32px 36px !important;
  gap: 2px 8px !important;
  padding: 9px 12px !important;
  box-sizing: border-box !important;
  height: 100% !important;
  width: 100% !important;
  align-items: center !important;
}
.bubble-background { inset: 0 !important; background: transparent !important; }
.bubble-content-container, .bubble-name-container { display: contents !important; }
.bubble-main-icon-container, .bubble-state { display: none !important; }
.bubble-name {
  grid-column: 1 !important;
  grid-row: 1 !important;
  display: block !important;
  color: var(--primary-text-color, #1f2937) !important;
  font-size: 15px !important;
  line-height: 16px !important;
  font-weight: 650 !important;
  white-space: normal !important;
  overflow: visible !important;
  text-overflow: clip !important;
  text-shadow: none !important;
  margin: 0 !important;
  pointer-events: none !important;
}
.bubble-name-container::after {
  content: var(--zone-caption);
  grid-column: 1;
  grid-row: 2;
  align-self: center;
  color: var(--zone-ink);
  font-size: 11px;
  line-height: 14px;
  font-weight: 500;
  white-space: normal;
  pointer-events: none;
}
.bubble-sub-button-container {
  grid-column: 2 !important;
  grid-row: 1 !important;
  display: grid !important;
  grid-template-columns: 32px 32px minmax(0,1fr) !important;
  grid-template-rows: 32px !important;
  grid-auto-flow: row !important;
  gap: 4px !important;
  position: relative !important;
  inset: auto !important;
  width: 152px !important;
  margin: 0 !important;
}
.bubble-sub-button {
  height: 32px !important;
  width: 32px !important;
  min-width: 0 !important;
  padding: 0 !important;
  justify-content: center !important;
  border-radius: 10px !important;
  box-shadow: none !important;
  text-shadow: none !important;
}
.bubble-sub-button:nth-child(2) {
  background: ${hass.states['input_boolean.sklep_michal_manual_override']?.state === 'on' ? '#fef3c7' : 'var(--secondary-background-color, #f3f4f6)'} !important;
  color: ${hass.states['input_boolean.sklep_michal_manual_override']?.state === 'on' ? '#92400e' : 'var(--secondary-text-color, #64748b)'} !important;
}
.bubble-sub-button:nth-child(3) {
  background: ${hass.states['input_boolean.schedule_enable_sklep_michal']?.state === 'on' ? '#dbeafe' : 'var(--secondary-background-color, #f3f4f6)'} !important;
  color: ${hass.states['input_boolean.schedule_enable_sklep_michal']?.state === 'on' ? '#1d4ed8' : 'var(--secondary-text-color, #64748b)'} !important;
}
.bubble-sub-button:nth-child(4) {
  width: 100% !important;
  background: transparent !important;
  color: var(--primary-text-color, #1f2937) !important;
  font-size: 19px !important;
  font-weight: 650 !important;
  letter-spacing: -0.5px !important;
  justify-content: flex-end !important;
}
.bubble-sub-button:nth-child(4) .bubble-sub-button-name-container {
  overflow: visible !important;
  white-space: nowrap !important;
}
.bubble-buttons-container {
  grid-column: 2 !important;
  grid-row: 2 !important;
  position: relative !important;
  inset: auto !important;
  width: 152px !important;
  margin: 0 !important;
  padding: 0 !important;
}
.bubble-temperature-container {
  width: 152px !important;
  height: 36px !important;
  background: var(--secondary-background-color, #f3f4f6) !important;
  color: var(--primary-text-color, #1f2937) !important;
  border-radius: 12px !important;
  justify-content: space-between !important;
}
.bubble-climate-minus-button, .bubble-climate-plus-button {
  flex: 0 0 38px !important;
  width: 38px !important;
  height: 36px !important;
  margin: 0 !important;
}
.bubble-climate-temp-display { font-size: 13px !important; padding: 0 !important; }

/* HEATING_STATE_GLOSS_20260918 */
.bubble-climate-container {
  --zone-rgb: var(--zone-rgb-value);
  --zone-sheen: ${hass.themes?.darkMode ? '0.08' : '0.70'};
  --zone-glow: ${hass.themes?.darkMode ? '0.20' : '0.13'};
  background:
    linear-gradient(125deg, rgba(255,255,255,var(--zone-sheen)) 0%, rgba(255,255,255,0) 48%),
    radial-gradient(ellipse at 100% 0%, rgba(var(--zone-rgb),var(--zone-glow)) 0%, rgba(var(--zone-rgb),0) 76%),
    linear-gradient(140deg, rgba(var(--zone-rgb),0.035), rgba(var(--zone-rgb),0.085)),
    var(--ha-card-background, var(--card-background-color, #fff)) !important;
  border: 1px solid rgba(var(--zone-rgb),0.20) !important;
  box-shadow:
    0 4px 12px -5px rgba(var(--zone-rgb),0.23),
    0 2px 4px rgba(15,23,42,0.035),
    inset 0 1px 0 rgba(255,255,255,var(--zone-sheen)),
    inset 0 -1px 0 rgba(var(--zone-rgb),0.045) !important;
  transition: box-shadow 180ms ease, border-color 180ms ease !important;
}
.bubble-temperature-container {
  background:
    linear-gradient(180deg, rgba(255,255,255,var(--zone-sheen)), rgba(255,255,255,0)),
    rgba(var(--zone-rgb),0.065) !important;
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,var(--zone-sheen)),
    inset 0 0 0 1px rgba(var(--zone-rgb),0.12) !important;
}
@media (hover: hover) and (pointer: fine) {
  .bubble-climate-container:hover {
    border-color: rgba(var(--zone-rgb),0.32) !important;
    box-shadow: 0 6px 16px -5px rgba(var(--zone-rgb),0.27),
      inset 0 1px 0 rgba(255,255,255,var(--zone-sheen)) !important;
  }
}
@media (prefers-reduced-motion: reduce) {
  .bubble-climate-container { transition: none !important; }
}

/* HEATING_SCHEDULE_ACCESS_20260918 */
.bubble-climate-container .bubble-name-container {
  display: flex !important;
  flex-direction: column !important;
  justify-content: center !important;
  align-items: flex-start !important;
  grid-column: 1 !important;
  grid-row: 1 !important;
  margin: 0 !important;
  min-width: 0 !important;
  gap: 2px !important;
}
.bubble-climate-container .bubble-name-container::after {
  align-self: flex-start !important;
}
.bubble-climate-container .bubble-sub-button-container {
  position: static !important;
}
.bubble-climate-container .bubble-sub-button:nth-child(5) {
  position: absolute !important;
  inset: auto !important;
  left: 12px !important;
  bottom: 9px !important;
  width: 88px !important;
  height: 32px !important;
  padding: 0 10px !important;
  justify-content: center !important;
  border-radius: 10px !important;
  background: rgba(var(--zone-rgb),0.075) !important;
  color: var(--primary-text-color, #1f2937) !important;
  box-shadow: inset 0 0 0 1px rgba(var(--zone-rgb),0.15) !important;
  font-size: 12px !important;
  font-weight: 600 !important;
  cursor: pointer !important;
  z-index: 2;
}

/* HEATING_STATUS_CLEAR_20260918 — display only */
${(() => {
  const getStatus = /* Display only. Uses the same effective override priority as central dispatch.
 * zone_*_aktivni is the zone request, not boiler relay or burner feedback. */
function zoneStatus(hass, entity) {
  const states = hass.states;
  const z = entity.split('.')[1];
  const e = states[entity];
  const state = id => states[id]?.state;
  const boolean = id => ['on', 'off'].includes(state(id));
  const number = value => value !== null && value !== undefined && String(value).trim() !== '' && Number.isFinite(Number(value)) ? Number(value) : null;
  const fmt = value => Number(value.toFixed(1)).toLocaleString('cs-CZ');
  const palette = {
    eco: ['#0f766e', '#5eead4'], schedule: ['#1d4ed8', '#93c5fd'],
    demand: ['#b45309', '#fcd34d'], manual: ['#7e22ce', '#d8b4fe'],
    off: ['#475569', '#cbd5e1'], error: ['#b91c1c', '#fca5a5'],
    unknown: ['#6b21a8', '#d8b4fe']
  };
  let kind = 'unknown';
  let label = 'Režim neznámý';
  let expected = null;
  const target = number(e?.attributes?.temperature);
  const requestState = state('binary_sensor.zona_' + z + '_aktivni');
  const demand = number(state('sensor.zona_' + z + '_demand'));
  const alive = state('binary_sensor.heating_valve_' + z + '_alive');
  const ready = e && !['unknown', 'unavailable', ''].includes(e.state) && alive === 'on';
  const requestKnown = ready && ['on', 'off'].includes(requestState) && demand !== null && demand >= 0 && demand <= 100;
  let request = 'Potřeba tepla: neznámo';
  if (requestKnown) request = requestState === 'on' ? 'Potřeba tepla: ano · ' + fmt(demand) + ' %' : 'Potřeba tepla: ne';
  const mode = state('input_select.topny_rezim');
  const enabled = state('input_boolean.topny_system_enable');
  const dispatch = state('input_boolean.heating_central_dispatch_enable');
  const guard = state('input_boolean.heating_startup_reconcile_guard');
  const manual = state('input_boolean.' + z + '_manual_override');
  const manualType = state('input_select.' + z + '_manual_override_type');
  const timer = state('timer.' + z + '_manual_override');
  const schedule = state('input_boolean.' + z + '_schedule_active');
  const boost = state('binary_sensor.kotel_boost_active');
  const eco = number(state('input_number.eco_temp_default'));
  const comfort = number(state('input_number.' + z + '_last_comfort'));
  const offset = number(state('input_number.boost_comfort_offset_c'));
  const manualKnown = ['on', 'off'].includes(manual) && (manual === 'off' || manualType === 'Do další změny rozvrhu' || (manualType === 'Časovač' && ['active', 'idle', 'paused'].includes(timer)));
  const manualEffective = manual === 'on' && (manualType === 'Do další změny rozvrhu' || (manualType === 'Časovač' && timer === 'active'));
  if (!e || e.state === 'unknown' || e.state === '') label = 'Hlavice: neznámý stav';
  else if (e.state === 'unavailable') { label = 'Hlavice nedostupná'; kind = 'error'; }
  else if (alive !== 'on') { label = 'Hlavice: chybí čerstvá data'; kind = 'error'; }
  else if (e.state === 'off') { label = 'Hlavice vypnutá'; kind = 'off'; }
  else if (enabled === 'off') { label = 'Řízení vypnuté'; kind = 'off'; }
  else if (mode === 'Off') { label = 'Režim Off'; kind = 'off'; }
  else if (dispatch === 'off') { label = 'Automatické řízení vypnuté'; kind = 'off'; }
  else if (guard === 'on') { label = 'Spouštění řízení'; kind = 'schedule'; }
  else if (enabled !== 'on' || dispatch !== 'on' || guard !== 'off' || !['Auto', 'Eco', 'Boost'].includes(mode) || !manualKnown || !boolean('binary_sensor.kotel_boost_active')) {
    label = 'Režim: chybí data';
  } else if (manualEffective) { label = 'Manuál'; kind = 'manual'; expected = comfort ?? eco; }
  else if (boost === 'on') { label = 'Boost'; kind = 'demand'; expected = (comfort ?? eco) !== null && offset !== null ? (comfort ?? eco) + offset : null; }
  else if (mode === 'Eco') { label = 'Útlum'; kind = 'eco'; expected = eco; }
  else if (schedule === 'on') { label = 'Rozvrh aktivní'; kind = 'schedule'; expected = comfort ?? eco; }
  else if (schedule === 'off') { label = 'Útlum'; kind = 'eco'; expected = eco; }
  else label = 'Rozvrh: chybí data';

  const min = number(e?.attributes?.min_temp) ?? 5;
  const max = number(e?.attributes?.max_temp) ?? 30;
  if (expected !== null) expected = Math.max(min, Math.min(max, expected));
  const lines = [label + (target !== null ? ' · ' + fmt(target) + ' °C' : ''), request];
  if (requestKnown && requestState === 'on' && !['error', 'unknown'].includes(kind)) kind = 'demand';
  if (!requestKnown && !['error', 'unknown'].includes(kind)) kind = 'unknown';
  const adaptation = states['sensor.' + z + '_stav_adaptacniho_behu']?.attributes?.In_progress;
  if (ready && adaptation === true) { lines.push('Probíhá adaptace'); if (kind !== 'error') kind = 'schedule'; }
  if (ready && target === null) { lines.push('Cílová teplota neznámá'); kind = 'unknown'; }
  if (ready && expected !== null && target !== null && Math.abs(expected - target) > 0.100001) {
    lines.push('Čeká na cíl ' + fmt(expected) + ' °C'); kind = 'error';
  }
  return {lines, color: palette[kind][0], ink: palette[kind][hass.themes?.darkMode ? 1 : 0], kind};
};
  const status = getStatus(hass, entity);
  const rgb = [1, 3, 5].map(i => parseInt(status.color.slice(i, i + 2), 16)).join(',');
  const caption = status.lines.map(line => JSON.stringify(line)).join(' "\\A " ');
  return '.bubble-climate-container { --zone-rgb-value: ' + rgb + '; --zone-ink: ' + status.ink + '; --zone-caption: ' + caption + '; }';
})()}
