cards.content:
{% set zones = [["sklep_michal","Sklep – Michal"],["prizemi_michal","Přízemí – Michal"],["prizemi_chodba_zachod","Přízemí – chodba/WC"],["1p_kuchyn","Kuchyň"],["1p_jidelna","Jídelna"],["1p_chodba","Chodba"],["1p_koupelna","Koupelna"],["2p_mama","Máma"]] %}
{% set ns = namespace(lines=[]) %}
{% for z, name in zones %}
  {% set e = 'sensor.' ~ z ~ '_chyba_softwaru' %}
  {% set a = 'sensor.' ~ z ~ '_stav_adaptacniho_behu' %}
  {% set c = 'climate.' ~ z %}
  {% if not has_value(c) %}
    {% set ns.lines = ns.lines + ['- **' ~ name ~ ':** hlavice je nedostupná nebo stav není známý.'] %}
  {% endif %}
  {% if is_state(e, 'something') %}
    {% if state_attr(e, 'Invalid_clock_information') == true %}
      {% set ns.lines = ns.lines + ['- **' ~ name ~ ':** čas hlavice není synchronizovaný.'] %}
    {% endif %}
    {% for key, label in [('Motor_error','chyba motoru'),('Encoder_jammed','zablokovaný enkodér'),('Radio_communication_error','chyba komunikace'),('Low_battery','slabá baterie'),('Critical_low_battery','kriticky slabá baterie'),('Top_pcb_sensor_error','chyba horního čidla'),('Side_pcb_sensor_error','chyba bočního čidla'),('Non_volatile_memory_error','chyba paměti'),('Unknown_hw_error','hardwarová chyba'),('Invalid_internal_communication','chyba interní komunikace')] %}
      {% if state_attr(e, key) == true %}
        {% set ns.lines = ns.lines + ['- **' ~ name ~ ':** ' ~ label ~ '.'] %}
      {% endif %}
    {% endfor %}
  {% elif not has_value(e) %}
    {% set ns.lines = ns.lines + ['- **' ~ name ~ ':** diagnostika závad není dostupná.'] %}
  {% endif %}
  {% if state_attr(a, 'In_progress') == true %}
    {% set ns.lines = ns.lines + ['- **' ~ name ~ ':** probíhá adaptace ventilu.'] %}
  {% elif state_attr(a, 'Valve_characteristic_found') == false %}
    {% set ns.lines = ns.lines + ['- **' ~ name ~ ':** adaptace ventilu není potvrzená.'] %}
  {% elif not has_value(a) %}
    {% set ns.lines = ns.lines + ['- **' ~ name ~ ':** stav adaptace není dostupný.'] %}
  {% endif %}
{% endfor %}
{{ ns.lines | join('\n') if ns.lines else 'Všechny hlavice jsou dostupné, bez hlášených závad a s potvrzenou adaptací.' }}

{% set demand = states('binary_sensor.kotel_should_be_on') %}
{% set relay = states('switch.kotel_rele_spinac') %}
{% set flame = states('binary_sensor.boiler_burngas') %}
{% set link = is_state('sensor.system_bus_status','connected') and is_state('binary_sensor.system_status','on') %}
{% set code = states('sensor.boiler_servicecodenumber') %}
{% set active = states('sensor.kotel_aktivni_zony_pocet') %}
{% set minimum = states('sensor.kotel_effective_min_active_zones') %}
{% set f = states('input_select.heating_flow_state_v4') %}
{% set temp = states('sensor.boiler_curflowtemp') %}
{% set yn = {'on':'Ano','off':'Ne'} %}
{% set protection = {'NORMAL':'Běžný provoz','EMERGENCY_COOLING':'Nouzové chlazení','RESTORING':'Obnova','HARD_LOCKOUT':'Blokace'} %}
{% if not link %}
## Spojení s kotlem vyžaduje kontrolu
{% elif flame == 'on' and relay == 'off' %}
## Hořák běží při rozepnutém topném relé
{% elif code in ['2964','2965','2966','2967'] %}
## Kotel hlásí poruchu {{ code }}
{% elif f in ['EMERGENCY_COOLING','RESTORING','HARD_LOCKOUT'] %}
## {{ protection[f] }}
{% elif is_state('input_boolean.heating_service_mode','on') %}
## Servisní režim
{% elif is_state('input_boolean.topny_system_enable','off') or is_state('input_select.topny_rezim','Off') %}
## Automatické vytápění je vypnuté
{% elif demand not in yn or relay not in yn or flame not in yn or f not in protection %}
## Část provozních údajů je nedostupná
{% elif flame == 'on' %}
## Hořák běží
{% elif relay == 'on' %}
## Topné relé je sepnuté
{% elif demand == 'on' %}
## Řízení žádá topení
{% else %}
## Řízení právě nežádá topení
{% endif %}

| Signál | Teď |
| :--- | :--- |
| Požadavek řízení | **{{ yn.get(demand,'—') }}** |
| Sepnuté topné relé | **{{ yn.get(relay,'—') }}** |
| Aktivní hořák | **{{ yn.get(flame,'—') if link else '—' }}** |
| Žádající zóny / minimum | {{ active if is_number(active) else '—' }} / {{ minimum if is_number(minimum) else '—' }} |
| Výstupní voda | {{ temp ~ ' °C' if link and is_number(temp) else '—' }} |
| Režim / ochrana | {{ states('input_select.topny_rezim') if has_value('input_select.topny_rezim') else '—' }} · {{ protection.get(f,'stav neznámý') }} |

{% set zones = [["sklep_michal", "Sklep · Michal"], ["prizemi_michal", "Přízemí · Michal"], ["prizemi_chodba_zachod", "Přízemí · Chodba / WC"], ["1p_kuchyn", "Kuchyň"], ["1p_jidelna", "Jídelna"], ["1p_chodba", "Chodba"], ["1p_koupelna", "Koupelna"], ["2p_mama", "2. patro · Máma"]] %}
{% set ns=namespace(lines=[]) %}
{% for e,label in [('binary_sensor.heating_core_v4_healthy','Automatizace řízení'),('binary_sensor.heating_dispatch_inputs_available','Vstupy řízení'),('binary_sensor.system_status','Spojení s kotlem')] %}
{% if not is_state(e,'on') %}{% set ns.lines=ns.lines+['- **' ~ label ~ ':** ' ~ ('problém / výpadek.' if is_state(e,'off') else 'stav neznámý.')] %}{% endif %}
{% endfor %}
{% for e,label in [('input_boolean.topny_system_enable','Hlavní řízení'),('input_boolean.heating_central_dispatch_enable','Předávání teplot do hlavic')] %}
{% if not is_state(e,'on') %}{% set ns.lines=ns.lines+['- **' ~ label ~ ':** ' ~ ('vypnuté.' if is_state(e,'off') else 'stav neznámý.')] %}{% endif %}
{% endfor %}
{% for z,name in zones %}
{% set c='climate.' ~ z %}{% set a='sensor.' ~ z ~ '_stav_adaptacniho_behu' %}{% set err='sensor.' ~ z ~ '_chyba_softwaru' %}
{% if not has_value(c) or not is_state('binary_sensor.heating_valve_' ~ z ~ '_alive','on') %}
{% set ns.lines=ns.lines+['- **' ~ name ~ ':** hlavice nemá ověřená aktuální data.'] %}
{% endif %}
{% if not has_value(err) %}{% set ns.lines=ns.lines+['- **' ~ name ~ ':** diagnostika závad není dostupná.'] %}
{% elif is_state(err,'something') %}{% set ns.lines=ns.lines+['- **' ~ name ~ ':** hlavice hlásí závadu; otevři detail.'] %}{% endif %}
{% if not has_value(a) %}{% set ns.lines=ns.lines+['- **' ~ name ~ ':** stav adaptace není dostupný.'] %}
{% elif state_attr(a,'In_progress') == true %}{% set ns.lines=ns.lines+['- **' ~ name ~ ':** probíhá adaptace ventilu.'] %}
{% elif state_attr(a,'Valve_characteristic_lost') == true %}{% set ns.lines=ns.lines+['- **' ~ name ~ ':** charakteristika ventilu byla ztracena.'] %}
{% elif state_attr(a,'Valve_characteristic_found') != true %}{% set ns.lines=ns.lines+['- **' ~ name ~ ':** adaptace ventilu není potvrzená.'] %}{% endif %}
{% endfor %}
{% if is_state('input_boolean.heating_startup_reconcile_guard','on') %}{% set ns.lines=ns.lines+['- Probíhá obnova řízení po startu.'] %}{% endif %}
{% if is_state('sensor.kotel_efficiency_rating','Kritické cyklování!') %}
{% set ns.lines=ns.lines+['- **Cyklování:** stávající diagnostika hodnotí posledních 24 h jako kritické. Nejde o měřenou účinnost.'] %}
{% elif not has_value('sensor.kotel_efficiency_rating') %}{% set ns.lines=ns.lines+['- Hodnocení cyklování není dostupné.'] %}{% endif %}
## {{ 'Vyžaduje pozornost' if ns.lines else 'Diagnostika bez hlášených problémů' }}
{{ ns.lines | join('
') if ns.lines else 'Kontrolované automatizace, spojení a diagnostika hlavic jsou v pořádku.' }}

