cards.content:
{% set zones=[
  ('Sklep · Michal','input_text.ph_sklep_michal_status','sklep_michal'),
  ('Přízemí · Michal','input_text.ph_prizemi_michal_status','prizemi_michal'),
  ('Přízemí · Chodba/WC','input_text.ph_prizemi_chodba_zachod_status','prizemi_chodba_zachod'),
  ('1P · Jídelna','input_text.ph_1p_jidelna_status','1p_jidelna'),
  ('1P · Kuchyň','input_text.ph_1p_kuchyn_status','1p_kuchyn'),
  ('1P · Koupelna','input_text.ph_1p_koupelna_status','1p_koupelna'),
  ('1P · Chodba','input_text.ph_1p_chodba_status','1p_chodba'),
  ('2P · Máma','input_text.ph_2p_mama_status','2p_mama')
] %}
{% set hb=as_timestamp(states('input_datetime.predictive_heating_heartbeat'), none) %}
{% set age=(as_timestamp(now())-hb) if hb is not none else none %}
## 🧠 Prediktivní topení
{% if is_state('input_boolean.predictive_heating_enable','on') and is_state('input_boolean.predictive_heating_shadow_mode','on') %}
**Shadow Mode** · měří, předpovídá a učí se — topení neovládá
{% elif is_state('input_boolean.predictive_heating_enable','on') %}
**Aktivní**
{% else %}
**Vypnuto**
{% endif %}
{% if is_number(state_attr('weather.forecast_domov','temperature')) %}
Venku **{{ state_attr('weather.forecast_domov','temperature')|round(1) }} °C** · vítr **{{ state_attr('weather.forecast_domov','wind_speed')|float(0)|round(0)|int }} km/h** · oblačnost **{{ state_attr('weather.forecast_domov','cloud_coverage')|float(0)|round(0)|int }} %**
{% endif %}
{% if age is none %}<small>Engine zatím neposlal výpočet.</small>{% elif age > 600 %}<small>⚠️ Poslední výpočet je starší než 10 minut.</small>{% else %}<small>Poslední výpočet před {{ (age/60)|round(0)|int }} min.</small>{% endif %}

| Místnost | Predikce a učení |
|:--|:--|
{% for name,e,z in zones -%}
{% set rate=states('input_number.ph_'~z~'_learned_rate')|float(default=none) -%}
{% set bias=states('input_number.ph_'~z~'_bias_min')|float(0) -%}
{% set delivery=states('input_number.ph_'~z~'_delivery_score')|float(0) -%}
